        'arch.items': 1,       // v1 4 Sep 2026 (F15, run 2): configuration items per system — the copies the MAC counts
        'mac.draft': 1,        // v1 4 Sep 2026 (F15): Minimum Acceptable Configuration rules from the SDD
        'arch.systems': 1,     // v1 4 Sep 2026 (F15): systems + their functions from the SDD, traced to aircraft sub-functions
        'arch.decompose': 2,   // v2 30 Aug 2026: granularity band + split rule + document anchoring (F1 variance batch: 8/16/22 functions from one SDD)
        'arch.recommend': 1,
